<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="theme-color" content="#BB2528">
    <title>Menú | Mekatos</title>
    <link rel="stylesheet" href="{{ asset('css/app.css') }}">
    <link rel="stylesheet" href="{{ asset('css/mekatos-client.css') }}">
    <style>
        .client-tools{position:sticky;top:66px;z-index:40;padding:10px 0 12px;background:#f7f7f5}.client-tools-inner{display:flex;gap:10px;align-items:center}.menu-search{flex:1;min-height:44px;padding:10px 13px;border:1px solid #d8d8d5;border-radius:10px;background:#fff;color:#171717}.category-nav{display:flex;gap:7px;overflow-x:auto;padding:1px 0 3px;scrollbar-width:thin}.category-nav a{flex:0 0 auto;padding:8px 11px;border:1px solid #dededb;border-radius:999px;background:#fff;text-decoration:none;font-size:.78rem;font-weight:750;color:#555}.category-nav a:hover,.category-nav a.active{background:#171717;border-color:#171717;color:#fff}.search-empty{padding:50px 20px;text-align:center;background:#fff;border:1px solid #e5e5e2;border-radius:15px}.search-empty h2{margin:0 0 6px}.search-empty p{margin:0 0 18px;color:#777}.product-card[hidden],.menu-section[hidden]{display:none}.client-footer{text-align:center;color:#888;font-size:.78rem;padding:0 0 25px}.cart-count-label{white-space:nowrap}.client-header{transition:box-shadow .2s ease}.client-hero{padding:8px 0 0}.product-card{min-height:225px}.product-card.is-in-cart{border-color:#aaa;box-shadow:0 10px 28px rgba(0,0,0,.07)}.product-card .product-category-mark{display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;margin-bottom:10px;border-radius:9px;background:#f0f0ee;font-size:.9rem}.client-feedback{z-index:120}.cart-panel{display:flex;flex-direction:column}.cart-items{flex:1}.cart-empty-action{margin-top:10px}.cart-panel-footer{margin-top:auto}.client-confirm-card{max-height:min(90vh,720px);overflow:auto}.confirm-line strong:last-child{overflow-wrap:anywhere;text-align:right}.confirm-actions{position:sticky;bottom:0;padding-top:12px;background:#fff}.item-note{margin-top:8px}.item-note label{display:block}.item-note span{display:block;color:#777;font-size:.7rem;font-weight:750;margin-bottom:4px}.item-note textarea{display:block;width:100%;min-height:52px;resize:vertical;padding:7px 8px;border:1px solid #d8d8d5;border-radius:8px;background:#fff;font:inherit;font-size:.75rem}.cart-item{display:flex;flex-direction:column;gap:8px;padding:13px 0;border-bottom:1px solid #eee}.cart-item-main{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.cart-item-main>div:first-child{min-width:0}.cart-item-main strong{display:block}.cart-item-main span{display:block;color:#777;font-size:.74rem;margin-top:2px}.cart-item .qty{align-self:flex-end}.cart-note-preview{display:block!important;color:#555!important;background:#f7f7f5;padding:7px 8px;border-radius:7px;font-size:.72rem!important;line-height:1.35}.cart-note-preview::before{content:'Detalle: ';font-weight:750}.confirm-line-note{display:block!important;color:#666!important;font-size:.72rem!important;margin-top:3px}.juice-options{margin-top:12px;padding:10px;background:#f7f7f5;border:1px solid #e4e4e1;border-radius:9px}.juice-options label{display:block;font-size:.72rem;font-weight:750;color:#555;margin-bottom:8px}.juice-options select,.juice-options input{display:block;width:100%;min-height:38px;padding:8px 9px;border:1px solid #d5d5d2;border-radius:8px;background:#fff;font:inherit;font-size:.78rem}.juice-other{margin-top:8px}.juice-other[hidden]{display:none}.juice-config{display:block;color:#555!important;background:#f7f7f5;padding:7px 8px;border-radius:7px;font-size:.72rem!important;line-height:1.35;margin-top:5px}.juice-modal-card{width:min(92vw,440px);max-height:90vh;overflow:auto;background:#fff;border-radius:16px;padding:22px;box-shadow:0 20px 70px rgba(0,0,0,.25)}.juice-modal-card h2{margin:0 0 6px}.juice-modal-card>p{margin:0 0 18px;color:#777}.juice-field{margin-bottom:15px}.juice-field>span{display:block;margin-bottom:7px;font-size:.78rem;font-weight:800}.juice-field select,.juice-field input{width:100%;min-height:44px;padding:10px 11px;border:1px solid #d4d4d1;border-radius:9px;background:#fff;font:inherit}.juice-field small{display:block;color:#777;margin-top:5px;font-size:.7rem;line-height:1.35}.juice-field input[hidden]{display:none}.juice-modal-actions{display:grid;grid-template-columns:1fr 1.2fr;gap:9px;margin-top:20px}.client-page .button:focus-visible,.client-page input:focus-visible,.client-page textarea:focus-visible,.client-page select:focus-visible,.client-page a:focus-visible{outline:3px solid rgba(23,23,23,.2);outline-offset:2px}
        @media(max-width:760px){.client-tools{top:59px}.client-tools-inner{flex-direction:column;align-items:stretch}.menu-search{width:100%}.client-hero h1{font-size:2rem}.product-card{min-height:205px}.cart-panel{padding:18px}.client-header{padding-inline:12px}.client-header strong{font-size:1.1rem}.client-header .button{min-height:38px;padding-inline:11px}}
        @media(max-width:430px){.cart-count-label{display:none}.client-shell{width:min(100% - 20px,1240px)}.client-hero{padding-top:2px}.menu-section-heading{align-items:flex-start;flex-direction:column;gap:5px}.product-card{padding:15px}.confirm-actions,.juice-modal-actions{display:grid;grid-template-columns:1fr}.confirm-actions .button,.juice-modal-actions .button{width:100%}}
        @media(prefers-reduced-motion:reduce){.product-card,.client-header{transition:none}}
    </style>
</head>
<body class="client-page">
<header class="client-header">
    <div><strong>Mekatos</strong><span id="table-label">Cargando mesa...</span></div>
    <button class="button button-primary" id="cart-open" type="button" aria-label="Abrir carrito">🛒 <span class="cart-count-label">Carrito</span> (<span id="cart-count">0</span>)</button>
</header>
<main class="client-shell">
    <div id="client-error" class="alert alert-error" hidden role="alert"></div>
    <section class="client-hero"><span class="eyebrow">Menú digital</span><h1>¿Qué quieres pedir?</h1><p>Explora el menú, arma tu pedido y envíalo directamente a cocina.</p></section>
    <div class="client-tools" aria-label="Herramientas del menú">
        <div class="client-tools-inner"><input class="menu-search" id="menu-search" type="search" placeholder="Buscar hamburguesa, pollo, jugo..." autocomplete="off" aria-label="Buscar en el menú"></div>
        <nav class="category-nav" id="category-nav" aria-label="Categorías del menú"></nav>
    </div>
    <div id="menu-container" class="menu-container"><p class="loading-state">Cargando menú...</p></div>
    <div id="search-empty" class="search-empty" hidden><h2>No encontramos ese producto</h2><p>Prueba con otro nombre o revisa las categorías del menú.</p><button class="button" type="button" id="clear-search">Limpiar búsqueda</button></div>
</main>
<footer class="client-footer">Mekatos · Gracias por tu pedido</footer>

<div id="cart-drawer" class="cart-drawer" hidden>
    <div class="cart-overlay" id="cart-close"></div>
    <aside class="cart-panel" aria-label="Carrito" aria-labelledby="cart-title">
        <div class="cart-panel-header"><div><span class="eyebrow">Tu selección</span><h2 id="cart-title">Tu pedido</h2></div><button class="button button-small" id="cart-close-button" type="button">Cerrar</button></div>
        <div id="cart-items" class="cart-items"></div>
        <div class="cart-panel-footer">
            <label class="client-notes"><span>Notas para el pedido</span><textarea id="order-notes" rows="3" maxlength="2000" placeholder="Ej. El cliente recoge en 15 minutos..."></textarea></label>
            <div class="cart-total"><span>Total</span><strong id="cart-total">$0</strong></div>
            <button class="button button-primary client-submit" id="submit-order" type="button">Continuar</button>
        </div>
    </aside>
</div>

<div id="juice-modal" class="client-confirm" hidden role="dialog" aria-modal="true" aria-labelledby="juice-modal-title">
    <div class="juice-modal-card">
        <h2 id="juice-modal-title">Personaliza tu jugo</h2>
        <p>Selecciona la preparación y la fruta para el Jugo Natural Jarra.</p>
        <div class="juice-field"><span>Preparación</span><select id="juice-preparation"><option value="AGUA">En agua · $8.500</option><option value="LECHE">En leche · $9.500</option></select></div>
        <div class="juice-field"><span>Fruta</span><select id="juice-fruit"><option value="MARACUYA">Maracuyá</option><option value="LULO">Lulo</option><option value="MORA">Mora</option><option value="FRESA">Fresa</option><option value="OTRO">Otro</option></select></div>
        <div class="juice-field"><span>Si eliges "Otro"</span><input id="juice-other-fruit" type="text" maxlength="100" placeholder="Escribe la fruta" hidden><small id="juice-other-help">Solo es necesario si seleccionas "Otro".</small></div>
        <div class="juice-modal-actions"><button class="button" id="juice-cancel" type="button">Cancelar</button><button class="button button-primary" id="juice-confirm" type="button">Agregar jugo</button></div>
    </div>
</div>

<div id="order-confirm" class="client-confirm" hidden role="dialog" aria-modal="true" aria-labelledby="order-confirm-title">
    <div class="client-confirm-card">
        <h2 id="order-confirm-title">¿Confirmar pedido?</h2><p>Revisa productos, cantidades y detalles antes de enviarlo a cocina.</p>
        <div id="confirm-summary" class="confirm-summary"></div>
        <div class="confirm-actions"><button class="button" id="cancel-confirm" type="button">Seguir revisando</button><button class="button button-primary" id="accept-confirm" type="button">Sí, enviar pedido</button></div>
    </div>
</div>

<div id="confirmation" class="confirmation" hidden role="dialog" aria-modal="true" aria-labelledby="success-title">
    <div class="confirmation-card"><div class="confirmation-icon">✓</div><h2 id="success-title">¡Pedido enviado!</h2><p id="confirmation-text">Tu pedido fue recibido correctamente.</p><button class="button button-primary" id="new-order" type="button">Volver al menú</button></div>
</div>
<div id="client-feedback" class="client-feedback" aria-live="polite" aria-atomic="true"></div>

<script>
const TOKEN = @json($token);
const STORAGE_KEY = `mekatos-cart-${TOKEN}`;
const state = { table:null, products:[], cart:{}, itemNotes:{}, juiceOptions:{}, categories:[] };
const JUICE_FRUITS = @json($juiceFruits ?? \App\Support\JuiceOptions::FRUITS);
const JUICE_PREPARATIONS = {AGUA:'En agua',LECHE:'En leche'};
const money = value => '$' + Number(value).toLocaleString('es-CO',{maximumFractionDigits:0});
const showError = message => { const el=document.getElementById('client-error'); el.textContent=message; el.hidden=false; };
const hideError = () => document.getElementById('client-error').hidden=true;
function escapeHtml(v){return String(v??'').replace(/[&<>'\"]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[s]));}
function saveCart(){localStorage.setItem(STORAGE_KEY,JSON.stringify({cart:state.cart,itemNotes:state.itemNotes,juiceOptions:state.juiceOptions,notes:document.getElementById('order-notes').value}));}
function restoreCart(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(saved?.cart)state.cart=saved.cart;state.itemNotes=saved?.itemNotes||{};state.juiceOptions=saved?.juiceOptions||{};document.getElementById('order-notes').value=saved?.notes||'';}catch{state.cart={};state.itemNotes={};state.juiceOptions={};}}
function clearSavedCart(){localStorage.removeItem(STORAGE_KEY);}
function showToast(title,message,type='success'){const container=document.getElementById('client-feedback');const toast=document.createElement('div');toast.className=`client-toast ${type==='error'?'client-toast-error':''}`;toast.innerHTML=`<div class="client-toast-icon">${type==='error'?'!':'✓'}</div><div><strong>${escapeHtml(title)}</strong><span>${escapeHtml(message)}</span></div>`;container.appendChild(toast);requestAnimationFrame(()=>toast.classList.add('show'));setTimeout(()=>{toast.classList.remove('show');setTimeout(()=>toast.remove(),220)},2800);}
function categoryIcon(name){const n=name.toLowerCase();if(n.includes('hamburg'))return'🍔';if(n.includes('pollo'))return'🍗';if(n.includes('perro'))return'🌭';if(n.includes('salchip'))return'🍟';if(n.includes('pizza'))return'🍕';if(n.includes('bebida')||n.includes('jugo')||n.includes('gaseosa'))return'🥤';if(n.includes('cerveza'))return'🍺';if(n.includes('ensalada'))return'🥗';if(n.includes('carne')||n.includes('parrilla'))return'🥩';return'🍽️';}
function isJuice(p){return p?.name==='Jugo Natural Jarra';}
function juicePrice(preparation){return preparation==='LECHE'?9500:8500;}
function juiceLabel(options){if(!options)return '';const prep=JUICE_PREPARATIONS[options.preparation]||options.preparation;const fruit=options.fruit==='OTRO'?`Otro: ${options.otherFruit||''}`:(JUICE_FRUITS[options.fruit]||options.fruit);return `${prep} · ${fruit}`;}
function renderCategoryNav(categories){const nav=document.getElementById('category-nav');nav.innerHTML=categories.map(c=>`<a href="#category-${c.id}" data-category="${c.id}">${escapeHtml(c.name)}</a>`).join('');nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.querySelectorAll('a').forEach(x=>x.classList.remove('active'))));}
function renderMenu(categories){const container=document.getElementById('menu-container');const available=categories.map(c=>({...c,products:(c.products||[]).filter(p=>p.is_available)})).filter(c=>c.products.length);state.categories=available;state.products=available.flatMap(c=>c.products);renderCategoryNav(available);if(!available.length){container.innerHTML='<div class="empty-state">No hay productos disponibles en este momento.</div>';return;}container.innerHTML=available.map(c=>`<section class="menu-section" id="category-${c.id}" data-category-name="${escapeHtml(c.name).toLowerCase()}"><div class="menu-section-heading"><div><h2>${escapeHtml(c.name)}</h2></div><span>${c.products.length} productos</span></div><div class="product-grid">${c.products.map(p=>{const juice=isJuice(p);return`<article class="product-card" data-id="${p.id}" data-name="${escapeHtml(p.name).toLowerCase()}" data-category="${c.id}"><span class="product-category-mark">${categoryIcon(c.name)}</span><h3>${escapeHtml(p.name)}</h3><p>${escapeHtml(p.description||'')}</p><div class="product-card-footer"><strong>${money(p.price)}</strong>${juice?'<button class="button button-primary" type="button" data-action="juice" data-id="'+p.id+'">Personalizar</button>':'<button class="button button-primary" type="button" data-action="add" data-id="'+p.id+'">Agregar</button>'}</div></article>`;}).join('')}</div></section>`).join('');bindProductActions();filterMenu();}
function getProduct(id){return state.products.find(p=>String(p.id)===String(id));}
function cartKey(id){return String(id);}
function addProduct(id){const p=getProduct(id);if(!p)return;if(isJuice(p)){openJuiceModal(id,false);return;}const key=cartKey(id);state.cart[key]=(state.cart[key]||0)+1;saveCart();renderCart();showToast('Agregado',p.name);}
function changeQty(id,delta){const key=cartKey(id);const next=(state.cart[key]||0)+delta;if(next<=0){delete state.cart[key];delete state.itemNotes[key];delete state.juiceOptions[key];}else state.cart[key]=next;saveCart();renderCart();}
function setItemNote(id,value){const key=cartKey(id);const note=value.trim();if(note)state.itemNotes[key]=note;else delete state.itemNotes[key];saveCart();}
let pendingJuiceId=null,pendingJuiceEdit=false;
function toggleOtherFruit(){const select=document.getElementById('juice-fruit');const input=document.getElementById('juice-other-fruit');const isOther=select.value==='OTRO';input.hidden=!isOther;input.required=isOther;document.getElementById('juice-other-help').textContent=isOther?'Escribe la fruta que quieres.':'Solo es necesario si seleccionas "Otro".';}
function openJuiceModal(id,edit=false){const p=getProduct(id);if(!p||!isJuice(p))return;pendingJuiceId=id;pendingJuiceEdit=edit;const saved=state.juiceOptions[id]||{preparation:'AGUA',fruit:'MARACUYA',otherFruit:''};const fruitSelect=document.getElementById('juice-fruit');const currentFruit=saved.fruit||'MARACUYA';fruitSelect.innerHTML=Object.entries(JUICE_FRUITS).map(([value,label])=>`<option value="${value}">${escapeHtml(label)}</option>`).join('');fruitSelect.value=JUICE_FRUITS[currentFruit]?currentFruit:Object.keys(JUICE_FRUITS)[0]||'OTRO';document.getElementById('juice-preparation').value=saved.preparation||'AGUA';document.getElementById('juice-other-fruit').value=saved.otherFruit||'';toggleOtherFruit();document.getElementById('juice-modal').hidden=false;document.getElementById('juice-confirm').textContent=edit?'Guardar cambios':'Agregar jugo';document.body.style.overflow='hidden';document.getElementById('juice-preparation').focus();}
function closeJuiceModal(){document.getElementById('juice-modal').hidden=true;pendingJuiceId=null;pendingJuiceEdit=false;document.body.style.overflow='';}
function confirmJuice(){if(!pendingJuiceId)return;const preparation=document.getElementById('juice-preparation').value;const fruit=document.getElementById('juice-fruit').value;const otherFruit=document.getElementById('juice-other-fruit').value.trim();if(fruit==='OTRO'&&!otherFruit){showToast('Falta la fruta','Escribe qué fruta quieres.','error');return;}const key=cartKey(pendingJuiceId);state.juiceOptions[key]={preparation,fruit,otherFruit};if(!pendingJuiceEdit)state.cart[key]=(state.cart[key]||0)+1;saveCart();renderCart();const p=getProduct(pendingJuiceId);closeJuiceModal();showToast(pendingJuiceEdit?'Actualizado':'Agregado',p?.name||'Jugo');}
function renderCart(){const items=document.getElementById('cart-items');const entries=Object.entries(state.cart);let total=0,count=0;if(!entries.length){items.innerHTML='<div class="empty-state">Tu carrito está vacío.<br><button class="button cart-empty-action" type="button" id="cart-empty-action">Ver menú</button></div>';document.getElementById('cart-total').textContent=money(0);document.getElementById('cart-count').textContent='0';document.getElementById('cart-empty-action')?.addEventListener('click',()=>toggleCart(false));return;}items.innerHTML=entries.map(([id,qty])=>{const p=getProduct(id);if(!p)return'';const key=cartKey(id);const isJuiceItem=isJuice(p);const price=isJuiceItem?juicePrice(state.juiceOptions[key]?.preparation):Number(p.price);const note=state.itemNotes[key]||'';total+=price*qty;count+=qty;return`<div class="cart-item"><div class="cart-item-main"><div><strong>${escapeHtml(p.name)}</strong><span>${isJuiceItem?escapeHtml(juiceLabel(state.juiceOptions[key])):''}</span></div><strong>${money(price*qty)}</strong></div><div class="qty"><button type="button" data-qty="${id}" data-delta="-1">−</button><span>${qty}</span><button type="button" data-qty="${id}" data-delta="1">+</button></div>${isJuiceItem?`<button class="button button-small" type="button" data-edit-juice="${id}">Editar jugo</button>`:''}<div class="item-note"><label><span>Detalle de este producto</span><textarea maxlength="500" data-item-note="${id}" placeholder="Ej. Sin cebolla, extra queso...">${escapeHtml(note)}</textarea></label></div>${note?`<span class="cart-note-preview">${escapeHtml(note)}</span>`:''}</div>`;}).join('');document.getElementById('cart-total').textContent=money(total);document.getElementById('cart-count').textContent=String(count);items.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>changeQty(b.dataset.qty,Number(b.dataset.delta))));items.querySelectorAll('[data-edit-juice]').forEach(b=>b.addEventListener('click',()=>openJuiceModal(b.dataset.editJuice,true)));items.querySelectorAll('[data-item-note]').forEach(t=>{t.addEventListener('input',()=>setItemNote(t.dataset.itemNote,t.value));});}
function toggleCart(open){document.getElementById('cart-drawer').hidden=!open;if(open)renderCart();document.body.style.overflow=open?'hidden':'';}
function buildConfirmSummary(){const entries=Object.entries(state.cart);const summary=document.getElementById('confirm-summary');if(!entries.length){summary.innerHTML='<p>Tu carrito está vacío.</p>';return;}summary.innerHTML=entries.map(([id,qty])=>{const p=getProduct(id);if(!p)return'';const key=cartKey(id);const isJuiceItem=isJuice(p);const price=isJuiceItem?juicePrice(state.juiceOptions[key]?.preparation):Number(p.price);const note=state.itemNotes[key]||'';return`<div class="confirm-line"><div><strong>${qty} × ${escapeHtml(p.name)}</strong>${isJuiceItem?`<span class="confirm-line-note">${escapeHtml(juiceLabel(state.juiceOptions[key]))}</span>`:''}${note?`<span class="confirm-line-note">Detalle: ${escapeHtml(note)}</span>`:''}</div><strong>${money(price*qty)}</strong></div>`;}).join('');}
function openConfirmation(){if(!Object.keys(state.cart).length){showToast('Carrito vacío','Agrega al menos un producto.','error');return;}buildConfirmSummary();document.getElementById('order-confirm').hidden=false;document.body.style.overflow='hidden';}
function closeConfirmation(){document.getElementById('order-confirm').hidden=true;document.body.style.overflow='';}
function payloadItems(){return Object.entries(state.cart).map(([id,qty])=>{const key=cartKey(id);const item={product_id:Number(id),quantity:Number(qty)};const note=state.itemNotes[key]||'';if(note)item.notes=note;if(isJuice(getProduct(id)))item.juice_options=state.juiceOptions[key]||{};return item;});}
async function submitOrder(){const button=document.getElementById('accept-confirm');button.disabled=true;hideError();try{const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({token:TOKEN,notes:document.getElementById('order-notes').value.trim(),items:payloadItems()})});const data=await response.json().catch(()=>({}));if(!response.ok){throw new Error(data.message||'No fue posible enviar el pedido.');}clearSavedCart();state.cart={};state.itemNotes={};state.juiceOptions={};closeConfirmation();toggleCart(false);document.getElementById('confirmation-text').textContent=data.message||'Tu pedido fue recibido correctamente.';document.getElementById('confirmation').hidden=false;document.body.style.overflow='hidden';}catch(error){showError(error.message);showToast('No se pudo enviar',error.message,'error');}finally{button.disabled=false;}}
function closeSuccess(){document.getElementById('confirmation').hidden=true;document.body.style.overflow='';renderCart();}
function bindProductActions(){document.querySelectorAll('[data-action="add"]').forEach(b=>b.addEventListener('click',()=>addProduct(b.dataset.id)));document.querySelectorAll('[data-action="juice"]').forEach(b=>b.addEventListener('click',()=>openJuiceModal(b.dataset.id,false)));}
function filterMenu(){const q=document.getElementById('menu-search').value.trim().toLowerCase();let matches=0;document.querySelectorAll('.menu-section').forEach(section=>{let sectionMatches=0;section.querySelectorAll('.product-card').forEach(card=>{const name=card.dataset.name||'';const visible=!q||name.includes(q);card.hidden=!visible;if(visible)sectionMatches++;});section.hidden=sectionMatches===0;matches+=sectionMatches;});document.getElementById('search-empty').hidden=matches>0||!q;}
async function loadMenu(){hideError();try{const tableResponse=await fetch(`/api/table/${encodeURIComponent(TOKEN)}`,{headers:{Accept:'application/json'}});if(!tableResponse.ok)throw new Error('No se pudo cargar la mesa.');const tableData=await tableResponse.json();state.table=tableData;document.getElementById('table-label').textContent=tableData.table?.name||tableData.name||`Mesa ${tableData.number||''}`;const menuResponse=await fetch('/api/menu',{headers:{Accept:'application/json'}});if(!menuResponse.ok)throw new Error('No se pudo cargar el menú.');const menuData=await menuResponse.json();const categories=Array.isArray(menuData)?menuData:(menuData.categories||menuData.data||[]);renderMenu(categories);restoreCart();renderCart();}catch(error){showError(error.message||'No se pudo cargar el menú.');document.getElementById('menu-container').innerHTML='';}}
document.getElementById('cart-open').addEventListener('click',()=>toggleCart(true));document.getElementById('cart-close').addEventListener('click',()=>toggleCart(false));document.getElementById('cart-close-button').addEventListener('click',()=>toggleCart(false));document.getElementById('submit-order').addEventListener('click',openConfirmation);document.getElementById('cancel-confirm').addEventListener('click',closeConfirmation);document.getElementById('accept-confirm').addEventListener('click',submitOrder);document.getElementById('juice-cancel').addEventListener('click',closeJuiceModal);document.getElementById('juice-confirm').addEventListener('click',confirmJuice);document.getElementById('juice-fruit').addEventListener('change',toggleOtherFruit);document.getElementById('new-order').addEventListener('click',closeSuccess);document.getElementById('menu-search').addEventListener('input',filterMenu);document.getElementById('clear-search').addEventListener('click',()=>{document.getElementById('menu-search').value='';filterMenu();document.getElementById('menu-search').focus();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!document.getElementById('juice-modal').hidden)closeJuiceModal();else if(!document.getElementById('order-confirm').hidden)closeConfirmation();else if(!document.getElementById('confirmation').hidden)closeSuccess();else if(!document.getElementById('cart-drawer').hidden)toggleCart(false);}});loadMenu();
</script>
</body>
</html>
